def img(path, alt='', fit='cover'):
    return f'<img src="public/assets/{escape(path)}" alt="{escape(alt)}" style="object-fit:{fit}">'

def img_detail(path, alt='', fit='cover'):
    return f'<img src="../public/assets/{escape(path)}" alt="{escape(alt)}" style="object-fit:{fit}">'

def mini_metrics(metrics):
    return ''.join(f'<span><b>{escape(v)}</b> {escape(l)}</span>' for v,l in metrics[:3])

def make_home():
    proj_html=[]
    for i,p in enumerate(projects):
        cls='project rev' if i%2 else 'project'
        proj_html.append(f'''<a class="project-link" href="preview/{p['slug']}.html"><div class="{cls}"><div class="text"><div class="eyebrow">{p['num']} · {escape(p['discipline'])}</div><h3>{escape(p['title'])}</h3><p>{escape(p['question'])}</p><div class="mini-metrics">{mini_metrics(p.get('metrics',[]))}</div><div class="tags">{escape(p['tags'])}</div><div class="open">Open technical case study ↗</div></div><div class="visual">{img(p['hero'],p['title'],p.get('fit','cover'))}<div class="overlay"><small>Project {p['num']}</small><b>Click for detailed case study</b></div></div></div></a>''')
    study_html=[]
    for s in studies:
        study_html.append(f'''<a href="preview/{s['slug']}.html"><article class="card">{img(s['hero'],s['title'],s.get('fit','cover'))}<div><div class="eyebrow">{escape(s['domain'])}</div><h3>{escape(s['title'])}</h3><p>{escape(s['summary'])}</p><div class="open">Open case study ↗</div></div></article></a>''')
    return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alexandre Sigiridis-Schlepp — Engineering Portfolio</title><style>{CSS}</style></head><body>
<div class="nav"><div class="shell"><strong>A. Sigiridis-Schlepp</strong><div class="navlinks"><a href="#projects">Projects</a><a href="public/docs/alexandre-sigiridis-schlepp-cv.pdf" target="_blank">CV</a><a href="https://www.linkedin.com/in/alexandre-sigiridis-schlepp/" target="_blank">LinkedIn</a></div></div></div>
<main><section><div class="shell hero"><div><div class="eyebrow">Mechanical engineering · simulation · R&amp;D</div><h1>Alexandre<br>Sigiridis-Schlepp</h1><p class="lead">Mechanical Engineer — Numerical Simulation, Fluid Mechanics &amp; Computational Engineering</p><p class="copy">Arts et Métiers / KIT double-degree engineer focused on turning physical problems into verified numerical models. CFD, finite elements, thermomechanics, turbomachinery, mechanical design and scientific computing.</p><div class="buttons"><a class="btn primary" href="#projects">Explore projects</a><a class="btn" href="public/docs/alexandre-sigiridis-schlepp-cv.pdf" target="_blank">CV PDF</a><a class="btn" href="https://www.linkedin.com/in/alexandre-sigiridis-schlepp/" target="_blank">LinkedIn</a></div></div><div><div class="hero-main">{img('compressor-featured-iso.png','Compressor CFD', fit='contain')}<div class="overlay"><small>Featured simulation</small><b>Coupled axial-compressor rotor–stator stage</b></div></div><div class="thumbs"><div class="thumb">{img('multimorph-regimes.png')}</div><div class="thumb">{img('v4-engine.png', fit='contain')}</div><div class="thumb">{img('aero-airfoil-aoa10.png', fit='contain')}</div></div></div></div></section>
<div class="atlas-wrap"><div class="shell atlas"><div class="atlas-item">{img('multimorph-validation.png')}<span>Multiphase validation</span></div><div class="atlas-item">{img('compressor-coupled-stage.png')}<span>Turbomachinery</span></div><div class="atlas-item">{img('v4-engine.png', fit='contain')}<span>135° V4 engine</span></div><div class="atlas-item">{img('aero-airfoil-aoa10.png', fit='contain')}<span>External aerodynamics</span></div></div></div>
<section id="projects" class="section"><div class="shell"><div class="section-head"><div><div class="eyebrow">Selected engineering work</div><h2>Problem → physics → model → result.</h2></div><p>Every flagship project is clickable and opens a dedicated technical case-study page. Supporting reports and calculation files are linked directly where available.</p></div>{''.join(proj_html)}</div></section>
<section id="technical-work" class="studies section"><div class="shell"><div class="section-head"><div><div class="eyebrow">Engineering studies</div><h2>Additional technical work</h2></div><p>Shorter studies are also clickable and keep their modelling assumptions and limitations explicit.</p></div><div class="cards">{''.join(study_html)}</div></div></section>
</main><div class="footer"><div class="shell">Alexandre Sigiridis-Schlepp · Engineering portfolio preview · <a href="mailto:sigischlepp.alex@gmail.com">sigischlepp.alex@gmail.com</a></div></div></body></html>'''

def make_detail(item, is_study=False):
    rel_asset='../public/assets/'
    rel_docs='../public/docs/'
    gallery=item.get('gallery',[])
    if not gallery and not is_study:
        gallery=[]
    gallery_html=''
    if gallery:
        figs=[]
        for i,(src,title) in enumerate(gallery):
            wide=' wide' if i==0 and len(gallery)>1 else ''
            figs.append(f'<figure class="{wide.strip()}"><div class="gallery-img"><img src="{rel_asset}{escape(src)}" alt="{escape(title)}"></div><figcaption>{escape(title)}</figcaption></figure>')
        gallery_html=f'<div class="gallery">{"".join(figs)}</div>'
    metrics=''.join(f'<div class="metric"><b>{escape(v)}</b><span>{escape(l)}</span></div>' for v,l in item.get('metrics',[]))
    sections=''.join(f'<section class="detail-section"><div><div class="eyebrow">{str(i+1).zfill(2)}</div><h2>{escape(t)}</h2></div><p>{escape(b)}</p></section>' for i,(t,b) in enumerate(item.get('sections',[])))
    report=''
    if item.get('report'):
        report_label=item.get('report_label','Open technical report PDF')
        report=f'<a class="btn primary" href="{rel_docs}{escape(item["report"])}" target="_blank">{escape(report_label)} ↗</a>'
    subtitle=item.get('subtitle',item.get('summary',''))
    question=item.get('question',item.get('summary',''))
    discipline=item.get('discipline',item.get('domain','Engineering study'))
    return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(item['title'])} — Alexandre Sigiridis-Schlepp</title><style>{CSS}</style></head><body>
<div class="nav"><div class="shell"><strong>A. Sigiridis-Schlepp</strong><div class="navlinks"><a href="../OPEN-PREVIEW.html#projects">Projects</a><a href="../public/docs/alexandre-sigiridis-schlepp-cv.pdf" target="_blank">CV</a><a href="https://www.linkedin.com/in/alexandre-sigiridis-schlepp/" target="_blank">LinkedIn</a></div></div></div>
<header class="detail-head"><div class="shell"><a class="back" href="../OPEN-PREVIEW.html#{'technical-work' if is_study else 'projects'}">← Back to portfolio</a><div class="eyebrow" style="margin-top:32px">{escape(discipline)}</div><h1>{escape(item['title'])}</h1><p class="detail-sub">{escape(subtitle)}</p><p class="question">{escape(question)}</p><div class="buttons">{report}<a class="btn" href="../public/docs/alexandre-sigiridis-schlepp-cv.pdf" target="_blank">CV PDF</a></div></div></header>
<main class="shell"><div class="detail-hero"><img src="{rel_asset}{escape(item['hero'])}" alt="{escape(item['title'])}" style="object-fit:{item.get('fit','cover')}"></div>{f'<div class="metrics">{metrics}</div>' if metrics else ''}{gallery_html}{sections}<div class="cta"><a class="btn" href="../OPEN-PREVIEW.html#{'technical-work' if is_study else 'projects'}">← Back to portfolio</a><div>{report}</div></div></main>
<div class="footer"><div class="shell">Alexandre Sigiridis-Schlepp · {escape(item['title'])}</div></div></body></html>'''

(ROOT/'OPEN-PREVIEW.html').write_text(make_home(),encoding='utf-8')
for p in projects:
    (PREVIEW/f"{p['slug']}.html").write_text(make_detail(p),encoding='utf-8')
for s in studies:
    (PREVIEW/f"{s['slug']}.html").write_text(make_detail(s,True),encoding='utf-8')
print('Generated', 1+len(projects)+len(studies), 'offline preview pages')
